<?php
require_once __DIR__ . '/layout.php';
require_roles();
$clientList=clients();
$assets=rows('SELECT a.*,c.client_name FROM brand_assets a JOIN clients c ON c.id=a.client_id WHERE c.deleted_at IS NULL AND c.is_active=1 ORDER BY c.client_name,a.asset_type');
page_start('Brand assets','employee-brands-assets.php');
?><p class="muted">Client logos and saved brand files are shared with your team.</p><section class="panel"><h2>Client logos</h2><div class="table-scroll"><table><thead><tr><th>Logo</th><th>Client</th><th>Website</th><th>Download</th></tr></thead><tbody><?php if (!$clientList) empty_row(4); foreach ($clientList as $client): ?><tr><td><?php if ($client['logo_path']): ?><img class="client-logo" src="<?= h($client['logo_path']) ?>" alt="<?= h($client['client_name']) ?> logo"><?php else: ?>—<?php endif; ?></td><td><?= h($client['client_name']) ?></td><td><?= h($client['website_url']) ?></td><td><?php if ($client['logo_path']): ?><a href="<?= h($client['logo_path']) ?>" class="icon-button" download title="Download logo" aria-label="Download logo"><?= icon('download') ?></a><?php else: ?><span class="muted">No logo uploaded</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><h2>Brand files</h2><div class="table-scroll"><table><thead><tr><th>Client</th><th>Type</th><th>File</th><th>Download</th></tr></thead><tbody><?php if (!$assets) empty_row(4,'No additional brand files have been saved.'); foreach ($assets as $asset): ?><tr><td><?= h($asset['client_name']) ?></td><td><?= h($asset['asset_type']) ?></td><td><?= h($asset['title']) ?></td><td><a href="download-asset.php?id=<?= $asset['id'] ?>" class="icon-button" aria-label="Download file" title="Download file"><?= icon('download') ?></a></td></tr><?php endforeach; ?></tbody></table></div></section><?php page_end(); ?>
